import argparse
from pathlib import Path
import requests

ALLOWED_PREFIXES = ("http://127.0.0.1", "http://localhost")

def load_targets(path: Path):
    return [line.strip() for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]

def scan(targets):
    session = requests.Session()
    session.headers.update({"User-Agent": "WAS-Intern-Inventory/1.0"})
    rows = []
    for url in targets:
        if not url.startswith(ALLOWED_PREFIXES):
            raise ValueError(f"Out-of-scope target: {url}")
        try:
            response = session.get(url, timeout=5, allow_redirects=False)
            rows.append({
                "url": url,
                "status": response.status_code,
                "content_type": response.headers.get("Content-Type", ""),
                "content_security_policy": response.headers.get("Content-Security-Policy", ""),
                "strict_transport_security": response.headers.get("Strict-Transport-Security", ""),
                "x_content_type_options": response.headers.get("X-Content-Type-Options", ""),
                "referrer_policy": response.headers.get("Referrer-Policy", "")
            })
        except requests.RequestException as exc:
            rows.append({"url": url, "error": str(exc)})
    return rows

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Focused local web inventory")
    parser.add_argument("targets", type=Path)
    args = parser.parse_args()
    for row in scan(load_targets(args.targets)):
        print(row)

from dataclasses import dataclass

@dataclass(frozen=True)
class CookieReview:
    name: str
    secure: bool
    httponly: bool
    samesite: str
    path: str

def review(cookie: CookieReview, production_https: bool):
    findings = []
    if production_https and not cookie.secure:
        findings.append("Secure is missing for an HTTPS production session cookie.")
    if not cookie.httponly:
        findings.append("HttpOnly is missing for a session cookie and increases script-readable exposure.")
    if cookie.samesite.lower() not in {"strict", "lax"}:
        findings.append("SameSite should be deliberately selected and justified for the application flow.")
    if cookie.path != "/":
        findings.append("Review path scope; choose the narrowest scope that matches the session architecture.")
    return findings

if __name__ == "__main__":
    sample = CookieReview("__Host-session", True, True, "Lax", "/")
    print(review(sample, production_https=True))

