REQUIRED_HEADERS = {
    "content-security-policy": "required",
    "x-content-type-options": "nosniff",
    "referrer-policy": "deliberate-policy",
}

def review_headers(headers: dict[str, str], https_deployment: bool):
    normalized = {k.lower(): v for k, v in headers.items()}
    findings = []
    for name in REQUIRED_HEADERS:
        if name not in normalized:
            findings.append(f"Missing: {name}")
    if https_deployment and "strict-transport-security" not in normalized:
        findings.append("Missing: strict-transport-security for HTTPS deployment review")
    return findings

