import secrets
from functools import wraps
from flask import abort, session, request
from werkzeug.security import check_password_hash

def csrf_token():
    token = session.get("csrf_token")
    if token is None:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token
    return token

def require_csrf():
    expected = session.get("csrf_token")
    supplied = request.form.get("csrf_token") or request.headers.get("X-CSRF-Token")
    if not expected or not supplied or not secrets.compare_digest(expected, supplied):
        abort(400, description="Invalid CSRF token")

def login_user(user_id, role):
    session.clear()
    session["user_id"] = user_id
    session["role"] = role
    csrf_token()

def logout_user():
    session.clear()

def current_user_id():
    return session.get("user_id")

def require_login(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if current_user_id() is None:
            abort(401)
        return view(*args, **kwargs)
    return wrapped

def require_admin(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if current_user_id() is None:
            abort(401)
        if session.get("role") != "admin":
            abort(403)
        return view(*args, **kwargs)
    return wrapped

def verify_password(stored_hash, candidate):
    return check_password_hash(stored_hash, candidate)

def validate_case_text(value, max_length=2000):
    if not isinstance(value, str):
        abort(400, description="Expected text")
    value = value.strip()
    if not value or len(value) > max_length:
        abort(400, description="Invalid text length")
    return value

from flask import abort, flash, redirect, render_template, request, session, url_for

from .db import get_db
from .security import (
    csrf_token, current_user_id, login_user, logout_user, require_admin,
    require_csrf, require_login, validate_case_text, verify_password
)

def register_routes(app):
    @app.context_processor
    def inject_security_helpers():
        return {"csrf_token": csrf_token, "current_user_id": current_user_id}

    @app.get("/")
    def index():
        if current_user_id() is None:
            return redirect(url_for("login"))
        return redirect(url_for("dashboard"))

    @app.route("/login", methods=["GET", "POST"])
    def login():
        if request.method == "POST":
            require_csrf()
            username = request.form.get("username", "").strip()
            password = request.form.get("password", "")
            user = get_db().execute(
                "SELECT id, password_hash, role FROM users WHERE username = ?",
                (username,),
            ).fetchone()
            if user is None or not verify_password(user["password_hash"], password):
                flash("Invalid username or password")
                return render_template("login.html"), 401
            login_user(user["id"], user["role"])
            return redirect(url_for("dashboard"))
        return render_template("login.html")

    @app.post("/logout")
    @require_login
    def logout():
        require_csrf()
        logout_user()
        return redirect(url_for("login"))

    @app.get("/dashboard")
    @require_login
    def dashboard():
        rows = get_db().execute(
            "SELECT id, title, details, created_at FROM cases WHERE owner_id = ? ORDER BY id DESC",
            (current_user_id(),),
        ).fetchall()
        return render_template("dashboard.html", cases=rows, role=session.get("role"))

    @app.post("/cases")
    @require_login
    def create_case():
        require_csrf()
        title = validate_case_text(request.form.get("title", ""), 120)
        details = validate_case_text(request.form.get("details", ""), 2000)
        db = get_db()
        db.execute(
            "INSERT INTO cases (owner_id, title, details) VALUES (?, ?, ?)",
            (current_user_id(), title, details),
        )
        db.commit()
        return redirect(url_for("dashboard"))

    @app.get("/cases/<int:case_id>")
    @require_login
    def case_detail(case_id):
        row = get_db().execute(
            "SELECT id, owner_id, title, details, created_at FROM cases WHERE id = ?",
            (case_id,),
        ).fetchone()
        if row is None:
            abort(404)
        if row["owner_id"] != current_user_id():
            abort(403)
        return render_template("case.html", case=row)

    @app.post("/cases/<int:case_id>/delete")
    @require_login
    def delete_case(case_id):
        require_csrf()
        row = get_db().execute(
            "SELECT owner_id FROM cases WHERE id = ?",
            (case_id,),
        ).fetchone()
        if row is None:
            abort(404)
        if row["owner_id"] != current_user_id():
            abort(403)
        db = get_db()
        db.execute("DELETE FROM cases WHERE id = ?", (case_id,))
        db.commit()
        return redirect(url_for("dashboard"))

    @app.get("/admin/cases")
    @require_admin
    def admin_cases():
        rows = get_db().execute(
            "SELECT cases.id, cases.title, users.username AS owner, cases.created_at FROM cases JOIN users ON users.id = cases.owner_id ORDER BY cases.id DESC"
        ).fetchall()
        return render_template("admin_cases.html", cases=rows)

    @app.errorhandler(400)
    def bad_request(error):
        return render_template("error.html", code=400, message=error.description), 400

    @app.errorhandler(401)
    def unauthorized(_error):
        return render_template("error.html", code=401, message="Authentication required"), 401

    @app.errorhandler(403)
    def forbidden(_error):
        return render_template("error.html", code=403, message="You are not authorized to perform this action"), 403

    @app.errorhandler(404)
    def not_found(_error):
        return render_template("error.html", code=404, message="Resource not found"), 404

